-- =============================================================================================
-- Hand-written below this line: document text checks, archiving final; versions numbered per
-- document under a lock, only on active documents, with a server-chosen key under the tenant
-- prefix, an allowed type and at most 20 MB; checked once (PENDING -> READY | REJECTED), nothing
-- else ever changes. See docs/architecture/DATA_MODEL.md section 11 (Communications).
-- =============================================================================================

ALTER TABLE "documents" ADD CONSTRAINT "documents_text"
  CHECK ("title" = btrim("title") AND length("title") BETWEEN 1 AND 160
         AND ("description" IS NULL OR ("description" = btrim("description") AND length("description") BETWEEN 1 AND 2000)));
ALTER TABLE "documents" ADD CONSTRAINT "documents_archived"
  CHECK (("status" = 'ARCHIVED') = ("archived_at" IS NOT NULL));

CREATE FUNCTION app_document_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'ACTIVE' THEN
      RAISE EXCEPTION 'documents start active' USING ERRCODE = 'check_violation';
    END IF;
    NEW."created_at" := now();
    NEW."archived_at" := NULL;
    RETURN NEW;
  END IF;
  IF OLD."status" = 'ARCHIVED' THEN
    RAISE EXCEPTION 'document % is archived and no longer changes', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."created_by_user_id", NEW."created_at")
     IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."created_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'document % stays at its property', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  NEW."archived_at" := CASE WHEN NEW."status" = 'ARCHIVED' THEN now() ELSE NULL END;
  RETURN NEW;
END
$$;

CREATE TRIGGER "documents_guard"
  BEFORE INSERT OR UPDATE ON "documents"
  FOR EACH ROW EXECUTE FUNCTION app_document_guard();

ALTER TABLE "document_versions" ADD CONSTRAINT "document_versions_file"
  CHECK ("content_type" IN ('image/jpeg', 'image/png', 'image/webp', 'image/heic', 'application/pdf')
         AND "size_bytes" BETWEEN 1 AND 20971520
         AND "file_name" = btrim("file_name") AND length("file_name") BETWEEN 1 AND 200
         AND "file_name" !~ '[/\\"<>|*?:[:cntrl:]]'
         AND ("note" IS NULL OR ("note" = btrim("note") AND length("note") BETWEEN 1 AND 500)));
ALTER TABLE "document_versions" ADD CONSTRAINT "document_versions_key"
  CHECK ("storage_key" = 'org/' || "organisation_id" || '/prop/' || "property_id" || '/documents/' || "id");
ALTER TABLE "document_versions" ADD CONSTRAINT "document_versions_ready"
  CHECK (("status" = 'READY') = ("ready_at" IS NOT NULL));

CREATE FUNCTION app_document_version_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'PENDING' THEN
      RAISE EXCEPTION 'versions start pending' USING ERRCODE = 'check_violation';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('veyra.document:' || NEW."document_id"::text, 0));
    IF NOT EXISTS (SELECT 1 FROM "documents" WHERE "id" = NEW."document_id" AND "status" = 'ACTIVE') THEN
      RAISE EXCEPTION 'the document is archived' USING ERRCODE = 'check_violation';
    END IF;
    SELECT coalesce(max("version_number"), 0) + 1 INTO NEW."version_number"
      FROM "document_versions" WHERE "document_id" = NEW."document_id";
    NEW."created_at" := now();
    NEW."ready_at" := NULL;
    RETURN NEW;
  END IF;
  IF OLD."status" <> 'PENDING' OR NEW."status" NOT IN ('READY', 'REJECTED')
     OR (NEW."organisation_id", NEW."property_id", NEW."document_id", NEW."version_number", NEW."storage_key",
         NEW."file_name", NEW."content_type", NEW."size_bytes", NEW."note", NEW."uploaded_by_user_id", NEW."created_at")
        IS DISTINCT FROM
        (OLD."organisation_id", OLD."property_id", OLD."document_id", OLD."version_number", OLD."storage_key",
         OLD."file_name", OLD."content_type", OLD."size_bytes", OLD."note", OLD."uploaded_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'version % is checked once and never changes otherwise', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  NEW."ready_at" := CASE WHEN NEW."status" = 'READY' THEN now() END;
  RETURN NEW;
END
$$;

CREATE TRIGGER "document_versions_guard"
  BEFORE INSERT OR UPDATE ON "document_versions"
  FOR EACH ROW EXECUTE FUNCTION app_document_version_guard();

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['documents', 'document_versions'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;

REVOKE ALL ON "documents", "document_versions" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "documents", "document_versions" TO veyra_app;
